  const worldBossApi='/api/world-boss';
  function bossRaidStorageKey(){return `vocahero_secure_wb_raid_${window._fbAuth?.currentUser?.uid||'guest'}`;}
  function readBossRaid(){try{const value=JSON.parse(localStorage.getItem(bossRaidStorageKey())||'null');return value?.token&&Date.parse(value.expiresAt)>Date.now()?value:null;}catch{return null;}}
  function applyBossStatus(boss){if(!boss)return boss;window._applySecureWorldBossStatus?.(boss);return boss;}
  async function secureWorldBossStatus(){const {boss}=await request(worldBossApi,{action:'status'},window._fbAuth);return applyBossStatus(boss);}
  async function secureWorldBossStart(){try{if(readBossRaid())return true;const {raid}=await request(worldBossApi,{action:'start'},window._fbAuth);localStorage.setItem(bossRaidStorageKey(),JSON.stringify({token:raid.token,expiresAt:raid.expiresAt}));return true;}catch(error){alertError(error);return false;}}
  async function secureWorldBossContribute(damage){const raid=readBossRaid();if(!raid)throw new Error('월드보스 참전 시간이 끝났어요. 새로 시작해 주세요.');const result=await request(worldBossApi,{action:'contribute',raidToken:raid.token,damage},window._fbAuth);localStorage.removeItem(bossRaidStorageKey());applyBossStatus(result.boss);return result;}
  function writeRankList(id,entries,value){const root=$(id);if(!root)return;root.replaceChildren();if(!entries.length){root.textContent='아직 공개된 랭킹이 없어요.';return;}entries.forEach(entry=>{const row=document.createElement('div'),left=document.createElement('span'),ordinal=document.createElement('b'),right=document.createElement('span');row.className='flex items-center justify-between gap-2 border-b border-[#1c1c1c] py-1 text-xs';left.className='flex min-w-0 items-center gap-1 font-bold text-white';ordinal.className='shrink-0 text-gray-400';ordinal.textContent=entry.rank+'.';left.append(ordinal);right.className='shrink-0 font-extrabold text-sky-400';if(entry.guildName){const guild=document.createElement('span');guild.className='inline-block max-w-24 shrink-0 truncate border border-sky-400 bg-sky-950/60 px-1 py-0.5 text-[10px] text-sky-200 shadow-[0_0_7px_rgba(56,189,248,.65)]';guild.textContent=entry.guildName;left.append(guild);}if(entry.titleName){const presentation=window.getHeroTitlePresentation?.(entry.titleName)||{name:entry.titleName,style:'border-[#d97706] bg-[#1a1a1a] text-yellow-300'};const title=document.createElement('span');title.className='inline-block shrink-0 border px-1 py-0.5 text-[10px] '+presentation.style;title.textContent='['+presentation.name+']';left.append(title);}const nickname=document.createElement('span');nickname.className='min-w-0 truncate';nickname.textContent=entry.nickname||'용사';left.append(nickname);right.textContent=value(entry);row.append(left,right);root.append(row);});}  async function rank(){const [stage,gold,boss]=await Promise.allSettled([request(rankApi,{limit:100,sort:'stage'},window._fbAuth),request(rankApi,{limit:100,sort:'gold'},window._fbAuth),request(worldBossApi,{action:'status'},window._fbAuth)]);if(stage.status==='fulfilled'){writeRankList('hofStageList',stage.value.entries,e=>'스테이지 '+e.stage+'-'+(e.progress+1));const mine=(stage.value.entries.find(e=>e.isMe)||{}).rank||'-';if($('myStageRankText'))$('myStageRankText').textContent=mine==='-'?'-':mine+'위';}else if($('hofStageList'))$('hofStageList').textContent='스테이지 랭킹을 불러오지 못했어요.';if(gold.status==='fulfilled'){writeRankList('hofGoldList',gold.value.entries,e=>e.gold.toLocaleString()+' G');const mine=(gold.value.entries.find(e=>e.isMe)||{}).rank||'-';if($('myGoldRankText'))$('myGoldRankText').textContent=mine==='-'?'-':mine+'위';}else if($('hofGoldList'))$('hofGoldList').textContent='골드 랭킹을 불러오지 못했어요.';if(boss.status==='fulfilled'){writeRankList('hofBossList',boss.value.boss.top,e=>e.damage.toLocaleString()+' 피해');const mine=boss.value.boss.myRank||'-';if($('myBossRankText'))$('myBossRankText').textContent=mine==='-'?'-':mine+'위';}else{if($('hofBossList'))$('hofBossList').textContent='월드보스 기록을 불러오지 못했어요.';if($('myBossRankText'))$('myBossRankText').textContent='-';}}  async function rename(){if(!account)return;const first=!account.freeNicknameChangeUsed;const ask=()=>window.showInputModal?.({icon:'✏️',title:'영웅 닉네임 변경',message:first?'첫 번째 닉네임 변경은 무료예요.':'닉네임 변경에는 500 FP가 필요해요.',inputType:'text',inputPlaceholder:'새 닉네임',inputMaxLength:12,confirmLabel:'변경하기',cancelLabel:'취소',confirmFirst:true,onConfirm:async value=>{try{const result=await request(studentApi,{action:'rename',nickname:value},window._fbAuth);apply(result.account);gameState.name=result.account.nickname;tempCredentials={...(tempCredentials||{}),name:result.account.nickname};if(typeof initGameEngine==='function')initGameEngine();toast(result.cost===0?'무료로 닉네임을 변경했어요.':'500 FP로 닉네임을 변경했어요.');}catch(error){alertError(error);}}});if(window.showConfirm)window.showConfirm(first?'첫 번째 닉네임 변경은 무료예요. 변경할까요?':'500 FP를 사용해 닉네임을 변경할까요?',ask,null,{icon:'✏️',title:'영웅 닉네임 변경',yesLabel:'계속',noLabel:'취소'});else ask();}  async function teacherRequest(action,payload={}){return request(teacherApiUrl,{action,...payload},window._fbTeacherAuth);}
  let teacherClassesCache=[],teacherWordPacksCache=[],selectedTeacherManagedGuildId='';
  function switchTeacherTab(tab='overview'){document.querySelectorAll('[data-secure-teacher-panel]').forEach(panel=>panel.classList.toggle('hidden',panel.dataset.secureTeacherPanel!==tab));document.querySelectorAll('[data-secure-teacher-tab]').forEach(button=>{const active=button.dataset.secureTeacherTab===tab;button.className='secureTeacherTab border-r border-[#333] px-3 py-3 text-xs font-black transition '+(active?'bg-white text-black':'bg-[#090909] text-gray-400 hover:bg-[#151515] hover:text-white');button.setAttribute('aria-selected',String(active));});window.lucide?.createIcons?.();}
  function fillTeacherGuildPicker(id){const picker=$(id);if(!picker)return;const selected=picker.value||selectedTeacherManagedGuildId;picker.replaceChildren();const placeholder=document.createElement('option');placeholder.value='';placeholder.textContent='길드를 선택하세요';picker.append(placeholder);teacherClassesCache.forEach(guild=>{const option=document.createElement('option');option.value=guild.id;option.textContent=guild.guildName;option.selected=guild.id===selected;picker.append(option);});}
  function updateTeacherSummary(){const total=(key)=>teacherClassesCache.reduce((sum,guild)=>sum+Number(guild[key]||0),0);$('secureTeacherGuildCount').textContent=String(teacherClassesCache.length);$('secureTeacherMemberTotal').textContent=total('studentCount').toLocaleString()+'명';$('secureTeacherActiveTotal').textContent=total('activeStudentCount').toLocaleString()+'명';$('secureTeacherCorrectTotal').textContent=total('totalCorrect').toLocaleString()+'개';}
  function guildMetric(label,value,color){const box=document.createElement('div'),caption=document.createElement('span'),metric=document.createElement('b');box.className='border border-[#2d2d2d] bg-black/40 p-2';caption.className='block text-[8px] text-gray-500';caption.textContent=label;metric.className='mt-1 block text-xs '+color;metric.textContent=value;box.append(caption,metric);return box;}
  function renderTeacherGuildCards(){const list=$('secureClassList');list.replaceChildren();if(!teacherClassesCache.length){const empty=document.createElement('button');empty.type='button';empty.className='col-span-full border border-dashed border-violet-900/70 bg-violet-950/10 p-10 text-center text-xs text-gray-500 hover:border-violet-500';empty.textContent='관리 중인 길드가 없어요. 길드 창설·참여 탭에서 첫 길드를 만들어 주세요.';empty.onclick=()=>switchTeacherTab('create');list.append(empty);return;}teacherClassesCache.forEach(guild=>{const card=document.createElement('button'),header=document.createElement('div'),crest=document.createElement('span'),heading=document.createElement('div'),name=document.createElement('b'),level=document.createElement('span'),stats=document.createElement('div'),footer=document.createElement('div'),enter=document.createElement('span');card.type='button';card.className='group border border-[#333] bg-gradient-to-br from-[#101010] to-black p-4 text-left transition hover:-translate-y-0.5 hover:border-violet-500 hover:shadow-[0_0_22px_rgba(124,58,237,.2)]';header.className='flex items-center gap-3';crest.className='flex h-10 w-10 shrink-0 items-center justify-center border border-violet-600 bg-violet-950/40 text-xl';crest.textContent='🛡️';heading.className='min-w-0';name.className='block truncate text-base text-violet-200';name.textContent=guild.guildName;level.className='mt-1 block text-[9px] text-gray-500';level.textContent=guildWordPackLabel(guild.wordPackId);heading.append(name,level);header.append(crest,heading);stats.className='mt-4 grid grid-cols-3 gap-2';stats.append(guildMetric('길드원',Number(guild.studentCount||0).toLocaleString()+'명','text-sky-300'),guildMetric('학습 참여',Number(guild.activeStudentCount||0).toLocaleString()+'명','text-emerald-300'),guildMetric('누적 정답',Number(guild.totalCorrect||0).toLocaleString(),'text-yellow-300'));footer.className='mt-4 flex items-center justify-between border-t border-[#292929] pt-3 text-[9px] text-gray-500';footer.append(document.createTextNode('공동 관리자 '+Number(guild.managerCount||0).toLocaleString()+'명'));enter.className='font-bold text-violet-300 group-hover:text-white';enter.textContent='관리 화면 열기 →';footer.append(enter);card.append(header,stats,footer);card.onclick=()=>selectTeacherGuild(guild.id,'members');list.append(card);});window.lucide?.createIcons?.();}
  function renderTeacherMembers(members){const list=$('secureTeacherMembersList');list.replaceChildren();if(!members?.length){list.textContent='아직 가입한 길드원이 없어요.';list.className='p-5 text-center text-xs text-gray-500';return;}list.className='max-h-80 divide-y divide-[#222] overflow-y-auto text-xs';members.forEach(member=>{const row=document.createElement('div'),name=document.createElement('span'),stage=document.createElement('span'),correct=document.createElement('span'),mastered=document.createElement('span');row.className='grid grid-cols-[minmax(0,1fr)_auto_auto_auto] items-center gap-2 bg-[#090909] px-3 py-2.5';name.className='min-w-0 truncate font-bold text-white';name.textContent=member.nickname+' · '+Number(member.learningGrade||4)+'학년';stage.className='text-gray-300';stage.textContent='S'+Number(member.stage||1);correct.className='text-right text-yellow-300';correct.textContent=Number(member.totalCorrect||0).toLocaleString();mastered.className='text-right text-emerald-300';mastered.textContent=Number(member.masteredCount||0).toLocaleString();row.append(name,stage,correct,mastered);list.append(row);});}
  function renderTeacherWordPack(guild){const select=$('secureTeacherWordPack');select.replaceChildren();teacherWordPacksCache.forEach(pack=>{const option=document.createElement('option');option.value=pack.id;option.textContent=`${pack.label} (${Number(pack.wordCount||0).toLocaleString()}단어)`;option.selected=pack.id===guild.wordPackId;select.append(option);});}
  async function selectTeacherGuild(classId,tab='members'){const guild=teacherClassesCache.find(item=>item.id===classId);if(!guild)return;selectedTeacherManagedGuildId=guild.id;fillTeacherGuildPicker('secureTeacherGuildPicker');fillTeacherGuildPicker('secureTrialGuildPicker');$('secureTeacherGuildPicker').value=guild.id;$('secureTrialGuildPicker').value=guild.id;if(tab==='trials'){await openTeacherGuildTrial(guild);return;}switchTeacherTab('members');$('secureTeacherMembersEmpty').classList.add('hidden');$('secureTeacherMembersContent').classList.remove('hidden');$('secureTeacherMembersTitle').textContent=guild.guildName;$('secureTeacherSelectedMembers').textContent=Number(guild.studentCount||0).toLocaleString()+'명';$('secureTeacherSelectedCorrect').textContent=Number(guild.totalCorrect||0).toLocaleString()+'개';$('secureTeacherSelectedManagers').textContent=Number(guild.managerCount||0).toLocaleString()+'명';$('secureTeacherSelectedMastered').textContent='불러오는 중';renderTeacherWordPack(guild);$('secureTeacherMembersList').textContent='길드원을 불러오는 중...';try{const {details}=await teacherRequest('guildMembers',{classId:guild.id});const members=details.members||[];$('secureTeacherSelectedMembers').textContent=members.length.toLocaleString()+'명';$('secureTeacherSelectedCorrect').textContent=members.reduce((sum,member)=>sum+Number(member.totalCorrect||0),0).toLocaleString()+'개';$('secureTeacherSelectedMastered').textContent=members.reduce((sum,member)=>sum+Number(member.masteredCount||0),0).toLocaleString()+'개';renderTeacherMembers(members);}catch(error){$('secureTeacherMembersList').textContent='길드원 정보를 불러오지 못했어요.';alertError(error);}}
  async function changeTeacherWordPack(){const guild=teacherClassesCache.find(item=>item.id===selectedTeacherManagedGuildId),select=$('secureTeacherWordPack');if(!guild||!select)return;const previous=guild.wordPackId;select.disabled=true;try{const {assignment}=await teacherRequest('setClassWordPack',{classId:guild.id,wordPackId:select.value});guild.wordPackId=assignment.wordPackId;renderTeacherGuildCards();toast('길드 학습 단어를 바꿨어요.');}catch(error){select.value=previous;alertError(error);}finally{select.disabled=false;}}
  async function refreshClasses(){try{const [{classes},{wordPacks}]=await Promise.all([teacherRequest('listClasses'),teacherRequest('listWordPacks')]);teacherClassesCache=classes||[];teacherWordPacksCache=wordPacks||[];if(selectedTeacherManagedGuildId&&!teacherClassesCache.some(guild=>guild.id===selectedTeacherManagedGuildId))selectedTeacherManagedGuildId='';updateTeacherSummary();fillTeacherGuildPicker('secureTeacherGuildPicker');fillTeacherGuildPicker('secureTrialGuildPicker');renderTeacherGuildCards();}catch(error){alertError(error);}}  const teacherTrialTypes=[['meaning-choice','뜻 고르기'],['word-choice','영어 고르기'],['spelling','철자 입력'],['unscramble','철자 배열']];
  let selectedTrialGuildId='',teacherWrongAnalysis=null,selectedTrialGuild=null;
  function renderTeacherTrialReview(){const list=$('secureWrongWordList'),countSelect=$('secureTrialCount');if(!teacherWrongAnalysis)return;const count=Math.min(Number(countSelect.value)||5,teacherWrongAnalysis.words.length);list.replaceChildren();teacherWrongAnalysis.words.slice(0,count).forEach((entry,index)=>{const row=document.createElement('div'),word=document.createElement('b'),meaning=document.createElement('span'),wrong=document.createElement('span'),type=document.createElement('select');row.className='grid grid-cols-[auto_minmax(0,1fr)_auto_auto] items-center gap-2 border-b border-[#202020] py-1';word.className='text-white';meaning.className='truncate text-gray-400';wrong.className='text-rose-300';type.className='border border-[#3c3c3c] bg-[#171717] p-1 text-[10px] text-white';word.textContent=(index+1)+'. '+entry.word;meaning.textContent=entry.meaning;wrong.textContent=entry.wrongCount+'회';teacherTrialTypes.forEach(([value,label])=>{const option=document.createElement('option');option.value=value;option.textContent=label;option.selected=value===teacherTrialTypes[index%teacherTrialTypes.length][0];type.append(option);});type.dataset.trialWord=entry.word;row.append(word,meaning,wrong,type);list.append(row);});if(!count)list.textContent='아직 집계된 오답 단어가 없어요.';}
  function teacherTrialStatusText(analysis){const active=analysis.activeTrial;if(!active)return `참여 ${analysis.memberCount}명의 누적 오답 중 뜻이 등록된 ${analysis.words.length}개를 집계했어요.`;return `현재 시련 ${active.questionCount}문제 · 참여 ${active.participantCount}명 · 완료 ${active.completedCount}명 · 총 응시 ${active.attemptCount}회 · 재시험 ${active.retryCount}회 · 힌트 ${active.hintCount}회${active.expired?' · 기간 종료':''}`;}
  async function openTeacherGuildTrial(guild){if(!guild)return;selectedTeacherManagedGuildId=guild.id;selectedTrialGuildId=guild.id;selectedTrialGuild=guild;teacherWrongAnalysis=null;switchTeacherTab('trials');fillTeacherGuildPicker('secureTrialGuildPicker');$('secureTrialGuildPicker').value=guild.id;const panel=$('secureTrialPanel'),empty=$('secureTrialEmpty'),list=$('secureWrongWordList'),status=$('secureTrialStatus');empty?.classList.add('hidden');panel.classList.remove('hidden');$('secureTrialGuildName').textContent=guild.guildName+' · 오답 분석·시련';list.textContent='오답 단어를 불러오는 중...';status.textContent='길드 전체 누적 오답을 분석하는 중...';try{const {analysis}=await teacherRequest('guildWrongWords',{classId:guild.id});teacherWrongAnalysis=analysis;[...$('secureTrialCount').options].forEach(option=>{option.disabled=Number(option.value)>analysis.words.length;});if(Number($('secureTrialCount').value)>analysis.words.length)$('secureTrialCount').value=analysis.words.length>=5?'5':$('secureTrialCount').value;renderTeacherTrialReview();status.textContent=teacherTrialStatusText(analysis);}catch(error){list.textContent='오답 분석을 불러오지 못했어요.';alertError(error);}}
  async function createTeacherGuildTrial(){if(!selectedTrialGuildId||!teacherWrongAnalysis)return;const items=[...document.querySelectorAll('#secureWrongWordList select[data-trial-word]')].map(select=>({word:select.dataset.trialWord,type:select.value}));const count=items.length;if(count<5){alertError(new Error('시련을 만들려면 오답 단어가 5개 이상 필요해요.'));return;}const issue=async()=>{const button=$('secureCreateTrial'),status=$('secureTrialStatus');button.disabled=true;status.textContent='검토한 문제로 길드 시련을 준비하는 중...';try{const {trial}=await teacherRequest('createGuildTrial',{classId:selectedTrialGuildId,count,items});status.textContent=`${trial.questionCount}문제 시련을 보냈어요. 힌트 ${trial.maxHints}회, 완료 보상 ${trial.rewardGuildCoins} 길드 코인이에요.`;toast('길드원에게 새 오답 시련을 보냈어요.');await openTeacherGuildTrial(selectedTrialGuild);}catch(error){status.textContent='시련을 만들지 못했어요.';alertError(error);}finally{button.disabled=false;}};const message=`검토한 ${count}문제로 시련을 내릴까요?<br>힌트 ${Math.max(1,Math.ceil(count/5))}회, 완료 보상 ${count*5} 길드 코인이며 기존 활성 시련을 대신합니다.`;if(typeof window.showConfirm==='function')window.showConfirm(message,issue,null,{icon:'📝',title:'길드 시련 내리기',yesLabel:'시련 보내기',noLabel:'취소'});else issue();}
  async function makeCode(classId,type){try{const {invite}=await teacherRequest('createInvite',{classId,type});await navigator.clipboard?.writeText(invite.code).catch(()=>{});window.showAlert?.(`${type==='student'?'학생 초대':'공동 관리자'} 코드: <b>${invite.code}</b><br>복사가 허용된 경우 자동으로 복사했어요. 필요하면 QR 코드로 만들어 전달해 주세요.`,'🔑','초대 코드');}catch(error){alertError(error);}}
  async function teacherLogin(){try{await window._signInWithPopup(window._fbTeacherAuth,window._fbTeacherGoogleProvider);await teacherRequest('bootstrap');$('secureTeacherLoginBox').classList.add('hidden');$('secureTeacherDashboard').classList.remove('hidden');switchTeacherTab('overview');refreshClasses();}catch(error){alertError(error);}}
  function clearTeacherTrialSelection(){$('secureTrialPanel')?.classList.add('hidden');$('secureTrialEmpty')?.classList.remove('hidden');if($('secureTrialGuildPicker'))$('secureTrialGuildPicker').value='';selectedTrialGuildId='';selectedTrialGuild=null;teacherWrongAnalysis=null;}
  function bindGuildInterfaces(){document.querySelectorAll('[data-secure-guild-tab]').forEach(button=>button.onclick=()=>switchGuildTab(button.dataset.secureGuildTab));document.querySelectorAll('[data-secure-teacher-tab]').forEach(button=>button.onclick=()=>switchTeacherTab(button.dataset.secureTeacherTab));$('secureGuildChange').onclick=showGuildJoinControls;$('secureTeacherRefresh').onclick=refreshClasses;$('secureTeacherGuildPicker').onchange=event=>{if(event.target.value)selectTeacherGuild(event.target.value,'members');};$('secureTrialGuildPicker').onchange=event=>{const guild=teacherClassesCache.find(item=>item.id===event.target.value);if(guild)openTeacherGuildTrial(guild);else clearTeacherTrialSelection();};$('secureTeacherStudentInvite').onclick=()=>{if(selectedTeacherManagedGuildId)makeCode(selectedTeacherManagedGuildId,'student');};$('secureTeacherManagerInvite').onclick=()=>{if(selectedTeacherManagedGuildId)makeCode(selectedTeacherManagedGuildId,'manager');};$('secureTeacherWordPack').onchange=changeTeacherWordPack;$('secureTrialPanelClose').onclick=clearTeacherTrialSelection;switchGuildTab('overview');switchTeacherTab('overview');}
  function setupLegacySchoolSearch(){const input=$('legacySchool'),results=$('legacySchoolResults');if(!input||!results)return;let timer;const close=()=>{results.classList.add('hidden');results.replaceChildren();};input.addEventListener('input',()=>{delete input.dataset.selected;clearTimeout(timer);const query=input.value.trim();if(query.length<2){close();return;}timer=setTimeout(async()=>{try{const url='https://open.neis.go.kr/hub/schoolInfo?KEY=04f275416e194b508bbd3ad51e42d887&Type=json&pIndex=1&pSize=20&SCHUL_KND_SC_NM='+encodeURIComponent('초등학교')+'&SCHUL_NM='+encodeURIComponent(query);const response=await fetch(url);const data=await response.json();const schools=data?.schoolInfo?.[1]?.row?.filter(school=>school.SCHUL_KND_SC_NM==='초등학교')||[];results.replaceChildren();if(!schools.length){const empty=document.createElement('p');empty.className='p-2 text-gray-400';empty.textContent='검색 결과가 없어요.';results.append(empty);}schools.forEach(school=>{const button=document.createElement('button');button.type='button';button.className='block w-full border-b border-[#303030] px-2 py-2 text-left hover:bg-[#252525]';button.textContent=school.SCHUL_NM+' ('+school.LCTN_SC_NM+')';button.onclick=()=>{input.value=school.SCHUL_NM;input.dataset.selected=school.SCHUL_NM;close();};results.append(button);});results.classList.remove('hidden');}catch(error){console.error('학교 검색 오류:',error);results.replaceChildren();const failed=document.createElement('p');failed.className='p-2 text-red-300';failed.textContent='학교 검색에 실패했어요. 잠시 후 다시 시도해 주세요.';results.append(failed);results.classList.remove('hidden');}},300);});document.addEventListener('click',event=>{if(!input.parentElement.contains(event.target))close();});}
  function build(){document.body.insertAdjacentHTML('beforeend',studentMarkup()+teacherMarkup()+welcomeMarkup()+migrationNoticeMarkup()+guildMarkup()+guildTrialMarkup());$('secureNickname').value=nickname();$('secureNicknameRandom').onclick=()=>{$('secureNickname').value=nickname();};const consent=$('securePrivacyConsent'),startButton=$('secureStudentStart');const syncConsent=()=>{const agreed=consent.checked;startButton.disabled=!agreed;startButton.className=agreed?'py-3 bg-[#e22718] text-white font-bold':'py-3 bg-[#5f1a16] text-gray-400 font-bold cursor-not-allowed';startButton.textContent=agreed?'안전하게 시작하기':'필수 동의 후 시작하기';};consent.onchange=syncConsent;syncConsent();startButton.onclick=start;$('secureWelcomeStart').onclick=openSignup;$('secureWelcomeGoogle').onclick=signInStudentGoogle;$('secureWelcomeTeacher').onclick=openTeacher;$('secureMigrationNoticeClose').onclick=()=>hide('secureMigrationNotice');$('secureMigrationNoticeDismiss').onclick=()=>{localStorage.setItem('vocahero_hide_legacy_migration_notice_v1','1');hide('secureMigrationNotice');};$('secureLeaderboardVisibility').onclick=toggleLeaderboardVisibility;$('secureHeaderGuildOpen').onclick=openGuildJoin;$('secureGuildClose').onclick=closeGuildJoin;document.querySelector('[onclick="openSettingsModal()"]')?.addEventListener('click',()=>setTimeout(syncStudentAuthUI,0));window._fbOnAuthStateChanged?.(window._fbAuth,()=>syncStudentAuthUI());$('secureGuildJoin').onclick=joinGuild;$('secureGuildChange').onclick=()=>$('secureGuildJoinControls').classList.remove('hidden');$('secureGuildScan').onclick=()=>{startGuildScan();};$('secureGuildTrialSubmit').onclick=()=>answerGuildTrial();$('secureGuildTrialInput').onkeydown=event=>{if(event.key==='Enter'&&!event.isComposing)answerGuildTrial();};$('secureGuildTrialHint').onclick=useGuildTrialHint;window.addEventListener('pagehide',stopGuildScan);const mainPanel=$('secureStudentMainPanel'),migrationPanel=$('secureMigrationPanel'),studentBox=$('secureStudentModal').firstElementChild;const showMigration=show=>{mainPanel.style.display=show?'none':'flex';migrationPanel.style.display=show?'flex':'none';migrationPanel.style.flexDirection='column';migrationPanel.style.gap='1rem';const toggle=$('secureMigrationToggle');if(toggle)toggle.style.display=show?'none':'block';if(studentBox)studentBox.scrollTop=0;};window._openLegacyMigration=()=>{openSignup();showMigration(true);};$('secureSignupBack').onclick=backToWelcome;$('secureMigrationToggle').onclick=()=>showMigration(true);$('secureMigrationBack').onclick=()=>showMigration(false);$('secureMigrate').onclick=migrate;$('secureRecoverMigrated').onclick=recoverMigratedLegacy;$('secureMigrateGoogle').onclick=migrateGoogleLegacy;$('legacyGrade').onchange=()=>{const grade=Number($('legacyGrade').value);if(grade>=3&&grade<=6)$('secureGrade').value=String(grade);};setupLegacySchoolSearch();$('secureTeacherClose').onclick=()=>hide('secureTeacherModal');$('secureTeacherGoogle').onclick=teacherLogin;$('secureTeacherRefresh').onclick=refreshClasses;$('secureTrialPanelClose').onclick=()=>$('secureTrialPanel').classList.add('hidden');$('secureTrialCount').onchange=renderTeacherTrialReview;$('secureCreateTrial').onclick=createTeacherGuildTrial;$('secureCreateGuild').onclick=async()=>{try{await teacherRequest('createGuild',{guildName:$('secureGuildName').value,grade:Number($('secureClassGrade').value)});$('secureGuildName').value='';refreshClasses();toast('새 길드를 만들었어요.');}catch(error){alertError(error);}};$('secureJoinManager').onclick=async()=>{try{await teacherRequest('joinAsManager',{code:$('secureManagerCode').value});$('secureManagerCode').value='';refreshClasses();toast('공동 관리자로 참여했어요.');}catch(error){alertError(error);}};bindGuildInterfaces();window.lucide?.createIcons();}
  async function init(){build();try{const auth=await activeStudentAuth();if(typeof auth.authStateReady==='function')await auth.authStateReady();const returningUser=Boolean(auth.currentUser);if(!auth.currentUser)await window._fbSignInAnonymously(auth);if(returningUser)beginGameEntry('✨ 영혼석에서 모험 기록을 불러오는 중...');const {account:data}=await request(studentApi,{action:'load'},auth);if(data){if(!returningUser)beginGameEntry('✨ 영혼석에서 모험 기록을 불러오는 중...');clearLegacy();apply(await withAssignedWordPack(data));toast(`${data.nickname}님, 다시 만나서 반가워요. 영웅과 함께 전설의 여정을 떠나봐요.`);}else{cancelGameEntry('secureWelcomeModal');showMigrationNotice();}}catch(error){console.error(error);cancelGameEntry('secureWelcomeModal');alertError(new Error('안전한 계정을 준비하지 못했어요. 잠시 후 페이지를 새로고침해 주세요.'));}}  function openTeacher(){show('secureTeacherModal');if(window._fbTeacherAuth?.currentUser){$('secureTeacherLoginBox').classList.add('hidden');$('secureTeacherDashboard').classList.remove('hidden');switchTeacherTab('overview');refreshClasses();}}
